function aire(longueur: number, largeur: number): number {
  return longueur * largeur;
}

starter_code:
function prixCommande(prixUnitaire, quantite, livraison) {
  return prixUnitaire * quantite;
}

solution:
function prixCommande(prixUnitaire: number, quantite: number, livraison: boolean): number {
  const total = prixUnitaire * quantite;
  return livraison ? total + 1500 : total;
}
